    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(
    18	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    19	            List<ReservationListener> listeners) {
    20	        this.rooms = rooms;
    21	        this.store = store;
    22	        this.priceCalculator = priceCalculator;
    23	        this.listeners = List.copyOf(listeners);
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (!request.checkOut().isAfter(request.checkIn())) {
    28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    29	        }
    30	        if (request.guests() < 1) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    32	        }
    33	        Room room = rooms.find(request.roomNumber())
    34	                .orElseThrow(() -> new HotelException(
    35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    36	        if (request.guests() > room.capacity()) {
    37	            throw new HotelException(
    38	                    ErrorCode.CAPACITY_EXCEEDED,
    39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    40	        }
    41	        boolean roomTaken = store.all().stream()
    42	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    43	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    44	        if (roomTaken) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    49	        Reservation reservation = new Reservation(store.nextId(), request, price);
    50	        store.save(reservation);
    51	        return reservation;
    52	    }
    53	
    54	    public Reservation find(long reservationId) {
    55	        return store.find(reservationId)
    56	                .orElseThrow(() -> new HotelException(
    57	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    58	    }
    59	
    60	    /** The guest paid: the reservation is confirmed and the listeners are told. */
    61	    public synchronized Reservation confirm(long reservationId) {
    62	        Reservation reservation = find(reservationId);
    63	        if (reservation.status() != ReservationStatus.PENDING) {
    64	            throw notAllowed(reservation, "confirm");
    65	        }
    66	        reservation.confirmPayment();
    67	        Room room = roomOf(reservation);
    68	        listeners.forEach(listener -> listener.confirmed(reservation, room));
    69	        return reservation;
    70	    }
    71	
    72	    /**
    73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    74	     * reservation was never paid, so nothing comes back).
    75	     */
    76	    public synchronized Reservation cancel(long reservationId) {
    77	        Reservation reservation = find(reservationId);
    78	        if (reservation.status() != ReservationStatus.PENDING
    79	                && reservation.status() != ReservationStatus.CONFIRMED) {
    80	            throw notAllowed(reservation, "cancel");
    81	        }
    82	        BigDecimal refund = switch (reservation.ratePlan()) {
    83	            case STANDARD -> reservation.amountPaid();
    84	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    85	        };
    86	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    87	        reservation.cancel(refund);
    88	        if (wasConfirmed) {
    89	            Room room = roomOf(reservation);
    90	            listeners.forEach(listener -> listener.confirmedReservationCancelled(reservation, room));
    91	        }
    92	        return reservation;
    93	    }
    94	
    95	    public synchronized Reservation checkIn(long reservationId) {
    96	        Reservation reservation = find(reservationId);
    97	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    98	            throw notAllowed(reservation, "check in");
    99	        }
   100	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   101	        return reservation;
   102	    }
   103	
   104	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   105	    public synchronized ReservationReceipt checkOut(long reservationId) {
   106	        Reservation reservation = find(reservationId);
   107	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   108	            throw notAllowed(reservation, "check out");
   109	        }
   110	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   111	        return new ReservationReceipt(reservation, roomOf(reservation));
   112	    }
   113	
   114	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   115	    public ReservationReceipt receiptCopy(long reservationId) {
   116	        Reservation reservation = find(reservationId);
